from collections import Counter

class Solution:
    def countStudents(self, students: list[int], sandwiches: list[int]) -> int:
        count = Counter(students)
        for i, s in enumerate(sandwiches):
            if count[s] > 0:
                count[s] -= 1
            else:
                return len(sandwiches) - i
        return 0

